diff --git a/src/core/bench.c b/src/core/bench.c
index eb019025..358530e4 100644
--- a/src/core/bench.c
+++ b/src/core/bench.c
@@ -40,6 +40,8 @@ typedef struct {
     const char *setup;
     // Played over and over through warmup and measurement.
     const char *loop;
+    // The Shell stays open over the Deck App.
+    bool shell;
 } BenchScenario;

 static const BenchScenario SCENARIOS[] = {
@@ -52,6 +54,8 @@ static const BenchScenario SCENARIOS[] = {
     // Focus moves from the section list into the Scroll section's list, which then glides down and up under the
     // left stick: native scrolling with no React work.
     {"demo-scroll", "vitadeck-demo.vdapp", "rrrrrrrv>", "++++++++++----------"},
+    // The Shell open over minesweeper-idle's screen: Shell paint and the backdrop behind it.
+    {"minesweeper-shell", "minesweeper.vdapp", NULL, NULL, true},
 };
 #define SCENARIO_COUNT ((int)(sizeof(SCENARIOS) / sizeof(SCENARIOS[0])))

@@ -618,6 +622,11 @@ bool bench_update(const VdJsRuntime *runtime, bool *request_runtime_restart)
     return ui.state != STATE_DONE;
 }

+bool bench_shell_open(void)
+{
+    return g_active && ui.scenario && ui.scenario->shell;
+}
+
 void bench_apply_input(void)
 {
     input_apply_gamepad(&ui.sample);

diff --git a/src/core/bench.h b/src/core/bench.h
index bc4cffaa..39c0ed33 100644
--- a/src/core/bench.h
+++ b/src/core/bench.h
@@ -40,6 +40,8 @@ bool bench_active(void);
 // UI thread, first thing every frame. Advances the scenario and may ask for a Deck App Runtime Restart. Returns
 // false once every scenario ran and the result is written.
 bool bench_update(const VdJsRuntime *runtime, bool *request_runtime_restart);
+// UI thread: whether the running scenario wants the Shell open.
+bool bench_shell_open(void);
 // UI thread, in place of the input polls: applies this frame's scripted pad input.
 void bench_apply_input(void);
 void bench_frame_mark(VdBenchFrameSpan span);

diff --git a/src/main.c b/src/main.c
index 2e4c79af..afbc42d3 100644
--- a/src/main.c
+++ b/src/main.c
@@ -60,6 +67,9 @@ int main(int argc, char *argv[])
         if (!bench_update(&bootstrap.js_runtime, &request_runtime_restart)) break;
         shell_update(&shell, &request_runtime_restart);
         shell_poll_system_input(&shell, &request_runtime_restart);
+        if (bench_active() && bench_shell_open() != shell_is_visible(&shell)) {
+            shell_apply_system_input(&shell, &(VdShellInput){.start = true}, &request_runtime_restart);
+        }
         if (request_runtime_restart) {
             js_runtime_stop(&bootstrap.js_runtime);
             scroll_reset();
